    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserWebauthnCredential(
            uid: 'one',
            user: new UserRef('one'),
            autenticator: 'one',
            name: 'one',
            publicKey: 'one',
            signCount: 1,
            aaguid: 'one',
            deviceName: 'one',
            transportsJson: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserWebauthnCredential::calculatedFields();

        // @Assert
        $this->assertEquals([ 'createdAt', 'enabled'], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getAutenticator(), $other->getAutenticator());
        $this->assertTrue($one->isAutenticatorChanged());
        $this->assertEquals($one->getName(), $other->getName());
        $this->assertTrue($one->isNameChanged());
        $this->assertEquals($one->getPublicKey(), $other->getPublicKey());
        $this->assertTrue($one->isPublicKeyChanged());
        $this->assertEquals($one->getSignCount(), $other->getSignCount());
        $this->assertTrue($one->isSignCountChanged());
        $this->assertEquals($one->getAaguid(), $other->getAaguid());
        $this->assertTrue($one->isAaguidChanged());
        $this->assertEquals($one->getDeviceName(), $other->getDeviceName());
        $this->assertTrue($one->isDeviceNameChanged());
        $this->assertEquals($one->getTransportsJson(), $other->getTransportsJson());
        $this->assertTrue($one->isTransportsJsonChanged());
        $this->assertEquals($one->getLastUsedAt(), $other->getLastUsedAt());
        $this->assertTrue($one->isLastUsedAtChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
