    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserWebauthnCredential(
            uid: 'one',
            user: new UserRef('one'),
            autenticator: 'one',
            name: 'one',
            publicKey: 'one',
            signCount: 1,
            aaguid: 'one',
            deviceName: 'one',
            transportsJson: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['user']['$ref']);
        $this->assertEquals('one', $json['autenticator']);
        $this->assertEquals('one', $json['name']);
        $this->assertEquals(1, $json['signCount']);
        $this->assertEquals('one', $json['aaguid']);
        $this->assertEquals('one', $json['deviceName']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['createdAt']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['lastUsedAt']);
        $this->assertEquals(true, $json['enabled']);
        $this->assertEquals(1, $json['version']);
    }
