    public function test_enable_modify(): void
    {
        // @Arrange
        $source = new UserWebauthnCredential(
            uid: 'one',
            user: new UserRef('one'),
            autenticator: 'one',
            name: 'one',
            publicKey: 'one',
            signCount: 1,
            aaguid: 'one',
            deviceName: 'one',
            transportsJson: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );
        $sourceEnabled = false;
        $targetEnabled = true;
        $source = $source->withEnabled($sourceEnabled);

        // @Act
        $target = $source->enable();

        // @Assert
        $this->assertEquals(false, $source->isEnabled());
        $this->assertEquals($targetEnabled, $target->isEnabled());
        $this->assertNotEquals($sourceEnabled, $target->isEnabled());
    }
    public function test_disable_modify(): void
    {
        // @Arrange
        $source = new UserWebauthnCredential(
            uid: 'one',
            user: new UserRef('one'),
            autenticator: 'one',
            name: 'one',
            publicKey: 'one',
            signCount: 1,
            aaguid: 'one',
            deviceName: 'one',
            transportsJson: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );
        $sourceEnabled = true;
        $targetEnabled = false;
        $source = $source->withEnabled($sourceEnabled);

        // @Act
        $target = $source->disable();

        // @Assert
        $this->assertEquals(true, $source->isEnabled());
        $this->assertEquals($targetEnabled, $target->isEnabled());
        $this->assertNotEquals($sourceEnabled, $target->isEnabled());
    }
